const estructura = $input.item.json;
const blog = $('🔍 Parsear Contenido').first().json;
const presentacionId = $('📋 Slides: Copiar Template').first().json.id;
const slideImg = $('🖼️ Seleccionar Imagen Slide').first().json;

const pageElements = estructura.slides?.[0]?.pageElements || [];

// English slide content from Groq; fallback to blog title
const titulo = blog.slide_title || blog.titulo || 'Blog Post';
const extracto = blog.slide_description || (blog.extracto || '').slice(0, 120);

// Use JPEG/PNG image (Google Slides doesn't accept WebP)
const imageUrl = slideImg.slide_image_url || blog.featured_image_url || '';

// Adaptive font size
let fontSize = 52;
if (titulo.length > 15) fontSize = 40;
if (titulo.length > 22) fontSize = 32;
if (titulo.length > 30) fontSize = 26;

const textRequests = [
  { replaceAllText: { containsText: { text: '[titulo_post]',      matchCase: true }, replaceText: titulo   } },
  { replaceAllText: { containsText: { text: '[descripcion_post]', matchCase: true }, replaceText: extracto } }
];

const titleShape = pageElements.find(el =>
  (el.shape?.text?.textElements || []).some(te => (te.textRun?.content || '').includes('[titulo_post]'))
);
if (titleShape) {
  textRequests.push({
    updateTextStyle: {
      objectId: titleShape.objectId,
      textRange: { type: 'ALL' },
      style: { fontSize: { magnitude: fontSize, unit: 'PT' } },
      fields: 'fontSize'
    }
  });
}

let imageRequest = null;
if (imageUrl) {
  const imageElement = pageElements.find(el => el.image !== undefined);
  if (imageElement) {
    imageRequest = {
      requests: [{
        replaceImage: {
          imageObjectId: imageElement.objectId,
          url: imageUrl,
          imageReplaceMethod: 'CENTER_CROP'
        }
      }]
    };
  }
}

return [{ json: { presentacionId, textRequests, imageRequest, titulo } }];

const blog = $('🔧 Seleccionar Blog').first().json;

const systemPrompt = "You are an expert social media strategist and SEO specialist for Crating Express, a wood packaging and custom crating company based in Miami FL. You write B2B industrial content. ALL output MUST be in English. Respond ONLY with valid JSON, zero extra text.";

const userPrompt = [
  'BLOG TITLE: ' + blog.titulo,
  'BLOG EXCERPT: ' + (blog.extracto || '').slice(0, 300),
  'ARTICLE URL: ' + blog.url,
  '',
  "LINKEDIN HASHTAG RULE: The LAST line of the linkedin field MUST contain EXACTLY 7 hashtags separated by spaces, nothing else. #ISPM15 is MANDATORY in every post. Pick the other 6 from this pool: #WoodCrating #CustomCrating #WoodPackaging #IndustrialPackaging #FreightProtection #ExportCrating #HeavyEquipmentShipping #MiamiLogistics #ShippingCrates #SupplyChain #ExportPackaging #B2BLogistics #ManufacturingMiami. NEVER use generic hashtags like #business #marketing.\n\nINSTAGRAM HASHTAG RULE: After a blank line add EXACTLY 13 hashtags. Mix: 3 high-competition from (#packaging #logistics #shipping #manufacturing #miami), 5 medium-competition from (#woodpackaging #customcrating #industrialpackaging #woodencrates #freightprotection #heavyequipment #palletcrating), 5 niche from (#ISPM15 #woodcrating #exportcrating #cratingexpress #miamilogistics #exportpackaging #heavyequipmentcrating #industrialshipping).",
  "\n\nPLATFORM CONTENT REQUIREMENTS (all in English):\n\nlinkedin: 200-250 words total. First 2 lines = strong hook. Body = 2-3 short paragraphs with B2B keywords. CTA line with article URL. Blank line. Final line = EXACTLY 7 hashtags.\n\ninstagram: 80-120 word caption. First line = hook, no hashtags. 2-3 emojis. CTA at end. Blank line. EXACTLY 13 hashtags.\n\nfacebook: 120-150 words. Engaging question or bold fact. Conversational tone. 1-2 emojis. End with: Read more (URL). 4-5 hashtags.\n\nemail_subject: Max 45 chars. MUST be clearly and specifically about THIS blog's real topic (the BLOG TITLE above) - never a generic or unrelated phrase. Curiosity-driven framing of that same topic only. No spam words. Do NOT start with New article.\n\nemail_body: Valid HTML. H2 heading. 2 short paragraphs (150-200 words). CTA button linked to URL. Professional Crating Express closing.\n\nslide_title: MAX 6 words. Punchy English headline for a graphic slide. No subtitle, no punctuation at end. Example: \"Cut Crating Costs in South Florida\".\n\nslide_description: 1 sentence, max 20 words. Supports the slide_title. English only. No hashtags."
].join('\n');

return [{
  json: {
    model: 'llama-3.3-70b-versatile',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ],
    temperature: 0.7,
    max_tokens: 2200,
    response_format: { type: 'json_object' }
  }
}];

const url = $json.featured_image_url || "";
if (!url) return [];
return [{ json: { source_url: url, mime_type: "image/jpeg", alt_text: $json.titulo || "" } }];

// Seleccionar la mejor imagen JPEG/PNG para el slide
const mediaItems = $input.all().map(i => i.json);
const blog = $('🔧 Seleccionar Blog').first().json;

// mediaItems es array de imágenes del post (JPEG/PNG solamente)
// Excluir logos, íconos, badges
const EXCLUDE_KEYWORDS = ['logo', 'brand', 'icon', 'badge', 'seal', 'stamp', 'cert', 'award'];

const filtered = mediaItems.filter(m => {
  const urlLower = (m.source_url || '').toLowerCase();
  const altLower = (m.alt_text || '').toLowerCase();
  return !EXCLUDE_KEYWORDS.some(k => urlLower.includes(k) || altLower.includes(k));
});

let imageUrl = null;

// Preferir PNG sobre JPEG, luego primera disponible
const png = filtered.find(m => m.mime_type === 'image/png');
const jpg = filtered.find(m => ['image/jpeg','image/jpg'].includes(m.mime_type));
const best = png || jpg || filtered[0];

if (best) {
  imageUrl = best.source_url;
} else {
  // Fallback: convertir WebP a JPG (WordPress guarda el original)
  imageUrl = (blog.featured_image_url || '').replace(/\.webp$/, '.jpg');
}

return [{
  json: {
    ...blog,
    slide_image_url: imageUrl || blog.featured_image_url || ''
  }
}];

const blogs = $input.all();
const total = blogs.length;
// Pass through all items, but flag if low stock
return blogs.map((b,i) => ({json:{...b.json, _total_blogs: total, _low_stock: total < 5}}))

const leads = $input.all();
const blog  = $('🔍 Parsear Contenido').first().json;
const result = [];

for (const item of leads) {
  const d = item.json;
  if (!d.email) continue;
  if ((d.estado_email || '').toLowerCase() === 'bloqueado') continue;

  result.push({
    json: {
      email:          d.email,
      nombre:         d.nombre || d.Nombre || 'there',
      row_number:     d.row_number,
      blog_titulo:    blog.titulo,
      blog_url:       blog.url,
      blog_extracto:  blog.extracto,
      blog_imagen:    blog.featured_image_url,
      email_subject:  blog.email_subject,
      email_body:     blog.email_body,
    }
  });
}

return result;

