// Filtrar leads con email + deduplicar + enriquecer con datos del blog
const leads = $input.all();
const seen = new Set();
const result = [];

// Get blog data from upstream nodes (set once for all leads)
let blogUrl = '';
let blogTitulo = '';
let blogImagen = '';
let emailSubject = '';
let emailBody = '';

try {
  const parsed = $('🔍 Parsear Contenido').first().json;
  blogUrl       = parsed.url || '';
  blogTitulo    = parsed.titulo || '';
  blogImagen    = parsed.featured_image_url || '';
  emailSubject  = parsed.email_subject || '';
  emailBody     = parsed.email_body || '';
} catch(e) {}

// Fallback: try Seleccionar Blog directly
if (!blogUrl) {
  try {
    const blog = $('🔧 Seleccionar Blog').first().json;
    blogUrl    = blog.url || blog.link || '';
    blogTitulo = blog.titulo || blog.title?.rendered || '';
    blogImagen = blog.featured_image_url || '';
  } catch(e) {}
}

for (const item of leads) {
  const d = item.json;
  const email = (d.email || '').trim().toLowerCase();

  // Skip sin email
  if (!email) continue;

  // Skip duplicados (mismo email)
  if (seen.has(email)) continue;
  seen.add(email);

  result.push({
    json: {
      nombre:        d.nombre || d.name || d.empresa || 'there',
      email:         d.email.trim(),
      empresa:       d.empresa || d.nombre || '',
      nicho:         d.nicho || '',
      email_subject: emailSubject || `Crating Express — Secure Shipping for ${d.empresa || 'Your Business'}`,
      email_body:    emailBody,
      blog_url:      blogUrl,
      blog_titulo:   blogTitulo,
      blog_imagen:   blogImagen,
    }
  });
}

return result;
